        { q: "What did Bholi decide to do for the rest of her life?", options: ["Serve her parents in their old age and teach in the same school where she learned so much", "Go to a big city", "Marry someone else", "Stay locked in her room"], ans: 0, exp: "Education gave her dignity and courage to stand on her own feet as a teacher." },
        { q: "Who is the author of 'Bholi'?", options: ["K.A. Abbas", "Premchand", "R.K. Narayan", "Mulk Raj Anand"], ans: 0, exp: "Khwaja Ahmad Abbas wrote this inspiring story about the power of education." }
