        { q: "What does the word 'suffice' mean?", options: ["Be sufficient / enough", "Suffer", "Fail", "Increase"], ans: 0, exp: "'Would suffice' means hatred alone would be enough to destroy the earth." },
        { q: "What is the central message of 'Fire and Ice'?", options: ["Uncontrolled desires and hatred among humans will lead to self-destruction", "We should build fire in winter", "Ice is better than fire", "Science will save earth"], ans: 0, exp: "Human emotions like greed and hatred are as destructive as natural catastrophes." },
        { q: "How many lines are in the poem 'Fire and Ice'?", options: ["9 lines", "8 lines", "12 lines", "14 lines"], ans: 0, exp: "'Fire and Ice' is a compact 9-line poem." },
        { q: "Which poetic device is used in 'Some say the world will end in fire, Some say in ice'?", options: ["Anaphora and Symbolism", "Simile", "Onomatopoeia", "Hyperbole"], ans: 0, exp: "Repetition of 'Some say' at the start of consecutive lines is Anaphora." }
